import { spawn } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { isAbsolute, join } from 'node:path';

import { MOTION_PREVIEW_MAX_HEIGHT, MOTION_PREVIEW_MAX_WIDTH } from '../../models/motionPreview';

// Previews are uploaded by hand, so one decode at a time keeps the small instance's memory bounded.
let activeDecodes = 0;
const maximumActiveDecodes = 1;
const decodeTimeoutMs = 20_000;
const durationToleranceMs = 150;

const alignUp = (value: number, alignment: number) => Math.ceil(value / alignment) * alignment;

/**
 * Pixel budget for FFmpeg's `max_pixels`, which bounds the frames the stream really decodes whatever
 * the container claims. FFmpeg compares it with the width rounded up to its SIMD stride (64 at most),
 * and `ignorecrop` leaves whole 16-pixel macroblocks, so the largest legitimate clip in either
 * orientation fits (480 × 854 is the larger case: 512 × 864) while 720p and above still fail.
 */
const maximumDecodedPixels = Math.max(
    alignUp(alignUp(MOTION_PREVIEW_MAX_WIDTH, 16), 64) * alignUp(MOTION_PREVIEW_MAX_HEIGHT, 16),
    alignUp(alignUp(MOTION_PREVIEW_MAX_HEIGHT, 16), 64) * alignUp(MOTION_PREVIEW_MAX_WIDTH, 16)
);

export type MotionPreviewDecodeErrorCode = 'decoder_unavailable' | 'decode_timeout' | 'decode_failed' | 'decoder_busy';

/** Operational decode failures are retryable and expose only a fixed code, never paths or diagnostics. */
export class MotionPreviewDecodeError extends Error {
    readonly statusCode: number;

    constructor(readonly code: MotionPreviewDecodeErrorCode) {
        super(code);
        this.name = 'MotionPreviewDecodeError';
        this.statusCode = code === 'decoder_busy' ? 429 : 503;
    }
}

/** A decode that runs but does not match the inspected container is evidence against the clip. */
export class UndecodableMotionPreviewError extends Error {
    readonly statusCode = 400;
    readonly code = 'ADMIN_MOTION_PREVIEW_INVALID';

    constructor() {
        super('The motion preview could not be decoded completely.');
        this.name = 'UndecodableMotionPreviewError';
    }
}

const missingRuntimeCapability = (diagnostic: string) => [
    /unrecognized option\b/i,
    /unknown (?:decoder|input format|output format)\b/i,
    /decoder(?: \([^\r\n)]{1,80}\))? not found\b/i,
    /could not find decoder\b/i,
    /requested (?:input|output) format [^\r\n]{1,100} is not known\b/i,
    /error while loading shared libraries\b|library not loaded\b/i
].some((pattern) => pattern.test(diagnostic));

/**
 * Fully decodes the one video stream to a null muxer with bounded memory, threads, time, output
 * and diagnostics. No network protocol, shell, audio device or output file is used.
 */
export const decodeMotionPreviewVideo = async (
    file: Pick<Express.Multer.File, 'path' | 'buffer'>,
    expectedDurationMs: number,
    signal?: AbortSignal
) => {
    signal?.throwIfAborted();
    const binary = process.env.ROOM_AUDIO_FFMPEG_PATH || 'ffmpeg';
    if (binary !== 'ffmpeg' && !isAbsolute(binary)) throw new MotionPreviewDecodeError('decoder_unavailable');
    if (activeDecodes >= maximumActiveDecodes) throw new MotionPreviewDecodeError('decoder_busy');
    activeDecodes += 1;
    let directory: string | undefined;
    try {
        let input = file.path;
        if (!input) {
            directory = await mkdtemp(join(tmpdir(), 'archtree-motion-preview-'));
            input = join(directory, 'input.mp4');
            await writeFile(input, file.buffer, { mode: 0o600, signal });
        }
        if (!isAbsolute(input)) throw new MotionPreviewDecodeError('decode_failed');
        // Decoder options precede -i. SPS cropping is ignored so a large coded frame cannot shrink
        // its checked size by cropping; an oversized frame then fails as an ordinary decode error.
        const args = [
            '-hide_banner', '-nostdin', '-loglevel', 'error', '-nostats', '-xerror', '-max_error_rate', '0',
            '-max_alloc', '33554432', '-max_pixels', String(maximumDecodedPixels), '-flags2', '+ignorecrop',
            '-threads', '1', '-filter_threads', '1',
            '-protocol_whitelist', 'file,pipe', '-format_whitelist', 'mov', '-max_streams', '1',
            '-err_detect', 'crccheck+bitstream+buffer+explode', '-f', 'mov', '-i', input,
            '-map', '0:v:0', '-an', '-sn', '-dn', '-threads', '1', '-progress', 'pipe:1', '-f', 'null', '-'
        ];
        await new Promise<void>((resolve, reject) => {
            const child = spawn(binary, args, {
                shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
                env: { PATH: process.env.PATH, LANG: 'C', LC_ALL: 'C' }
            });
            let failure: Error | undefined;
            let pending = '';
            let outputBytes = 0;
            let diagnosticBytes = 0;
            let finalDurationMs = 0;
            let completed = false;
            let unavailable = false;
            let diagnosticTail = '';
            const stop = (error: Error) => { failure ??= error; child.kill('SIGKILL'); };
            const onAbort = () => stop(signal?.reason instanceof Error ? signal.reason : new DOMException('Aborted', 'AbortError'));
            const timer = setTimeout(() => stop(new MotionPreviewDecodeError('decode_timeout')), decodeTimeoutMs);
            signal?.addEventListener('abort', onAbort, { once: true });
            if (signal?.aborted) onAbort();
            child.stdout.on('data', (buffer: Buffer) => {
                outputBytes += buffer.length;
                if (outputBytes > 256 * 1024) { stop(new MotionPreviewDecodeError('decode_failed')); return; }
                pending += buffer.toString('utf8');
                if (pending.length > 8192) { stop(new MotionPreviewDecodeError('decode_failed')); return; }
                let newline: number;
                while ((newline = pending.indexOf('\n')) >= 0) {
                    const line = pending.slice(0, newline).trim();
                    pending = pending.slice(newline + 1);
                    if (line.startsWith('out_time_us=')) {
                        const value = line.slice(12);
                        // FFmpeg reports N/A before the first frame; any other value must be a bounded integer.
                        if (value === 'N/A') continue;
                        if (!/^\d{1,15}$/.test(value)) { stop(new UndecodableMotionPreviewError()); return; }
                        finalDurationMs = Number(value) / 1000;
                        if (finalDurationMs > expectedDurationMs + durationToleranceMs) {
                            stop(new UndecodableMotionPreviewError());
                            return;
                        }
                    } else if (line === 'progress=end') {
                        completed = true;
                    }
                }
            });
            child.stderr.on('data', (buffer: Buffer) => {
                const inspected = buffer.subarray(0, Math.max(0, 8192 - diagnosticBytes)).toString('utf8');
                const diagnostic = diagnosticTail + inspected;
                unavailable ||= missingRuntimeCapability(diagnostic);
                diagnosticTail = diagnostic.slice(-256);
                diagnosticBytes += buffer.length;
                if (diagnosticBytes > 8192) {
                    stop(unavailable ? new MotionPreviewDecodeError('decoder_unavailable') : new UndecodableMotionPreviewError());
                }
            });
            child.once('error', () => { failure ??= new MotionPreviewDecodeError('decoder_unavailable'); });
            child.once('close', (code, processSignal) => {
                clearTimeout(timer);
                signal?.removeEventListener('abort', onAbort);
                if (failure) reject(failure);
                else if (unavailable) reject(new MotionPreviewDecodeError('decoder_unavailable'));
                else if (processSignal) reject(new MotionPreviewDecodeError('decode_failed'));
                else if (code !== 0 || diagnosticBytes || !completed || !finalDurationMs
                    || Math.abs(finalDurationMs - expectedDurationMs) > Math.max(durationToleranceMs, expectedDurationMs * 0.05)) {
                    reject(new UndecodableMotionPreviewError());
                } else resolve();
            });
        });
    } finally {
        try { if (directory) await rm(directory, { recursive: true, force: true }); }
        finally { activeDecodes -= 1; }
    }
};
